<?php else: ?><form method="post" action="<?= e($postUrl) ?>"><input type="hidden" name="_csrf" value="<?= e(csrfToken()) ?>"><button type="submit" class="primary" name="acao" value="reativar">Reativar ficha</button></form><?php endif; ?>
